    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if (i,j) in seen: continue
            q=deque([(i,j)]); seen.add((i,j)); cc=[]
            while q:
                a,b=q.popleft(); cc.append((a,b))
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    na,nb=a+da,b+db
                    if 0<=na<h and 0<=nb<w and (na,nb) not in seen and g[na][nb]==g[a][b]:
                        seen.add((na,nb)); q.append((na,nb))
            out.append(cc)
    # return list of (color, compset, size)
    res=[]
    for cc in out:
        res.append((gi[cc[0][0]][cc[0][1]], frozenset(cc), len(cc)))
    return res
